"""Quarantine Reader interface and schema-bound extraction."""

import json
from typing import Any

from pydantic import BaseModel, Field

from twinlane.protocol.data import DataItem
from twinlane.protocol.errors import InvalidSchemaError
from twinlane.protocol.provenance import IntegrityLabel, Provenance


class QuarantineResult(BaseModel):
    """Output generated by Quarantine Reader."""

    parsed_fields: dict[str, Any] = Field(default_factory=dict)
    provenance: Provenance = Field(..., description="Tainted provenance attached to reader output")
    raw_text: str = ""

    model_config = {"extra": "forbid"}


class QuarantineReader:
    """Safely processes untrusted Data Lane content with zero tools.

    Outputs are schema-validated and guaranteed to retain an UNTRUSTED
    or EXTRACTED_UNTRUSTED label to prevent boundary laundering.
    """

    def process_data_item(
        self,
        item: DataItem,
        expected_keys: list[str] | None = None,
    ) -> QuarantineResult:
        """Parse and quarantine an untrusted DataItem.

        Args:
            item: DataItem to parse.
            expected_keys: Optional list of keys required in output.

        Raises:
            InvalidSchemaError: If output fails schema or formatting constraints.
        """
        raw_content = item.content or ""
        parsed_fields: dict[str, Any] = {}

        if item.media_type == "application/json":
            try:
                data = json.loads(raw_content)
                if isinstance(data, dict):
                    parsed_fields = data
            except json.JSONDecodeError as e:
                raise InvalidSchemaError(
                    f"Quarantine item '{item.item_id}' contains invalid JSON: {e}"
                ) from e

        if expected_keys:
            for k in expected_keys:
                if k not in parsed_fields:
                    raise InvalidSchemaError(f"Quarantine item missing expected field: '{k}'")

        # Non-Promotion Invariant: Output provenance is strictly UNTRUSTED
        out_prov = Provenance(
            origin=f"quarantine:{item.item_id}",
            origin_type=item.provenance.origin_type,
            chain=list(item.provenance.chain),
            integrity=IntegrityLabel.UNTRUSTED,
            confidentiality=item.provenance.confidentiality,
        )

        return QuarantineResult(
            parsed_fields=parsed_fields,
            provenance=out_prov,
            raw_text=raw_content,
        )
